WITH top_leser AS (  SELECT l.id, l.name FROM ausleihen a   JOIN leser l ON a.leser_id = l.id   GROUP BY l.id, l.name HAVING COUNT(*) >= 3), lieblings AS (  SELECT a.leser_id, b.autor_id, COUNT(*) AS anzahl   FROM ausleihen a JOIN buecher b ON a.buch_id = b.id   WHERE a.leser_id IN (SELECT id FROM top_leser)   GROUP BY a.leser_id, b.autor_id) SELECT tl.name AS leser, au.name AS autor, l.anzahl FROM lieblings l JOIN top_leser tl ON l.leser_id = tl.id JOIN autoren au ON l.autor_id = au.id ORDER BY tl.name, l.anzahl DESC, au.name;
